c1_08_hazard_field.solution:
while robot.scan_object("right") != "edge":
    if robot.scan_object("right") == "hazard":
        robot.move("up")
        robot.move("right")
        robot.move("right")
        robot.move("down")
    else:
        robot.move("right")
robot.action()

c1_09_reusable_routine.solution:
def dodge():
    robot.move("up")
    robot.move("right")
    robot.move("right")
    robot.move("down")

while robot.scan_object("right") != "edge":
    if robot.scan_object("right") == "hazard":
        dodge()
    else:
        robot.move("right")
robot.action()

